import{_ as e,o as a,c as n,a2 as s}from"./chunks/framework.DGu13UIe.js";const g=JSON.parse('{"title":"第 38 课 · 还要什么，才算 Code Agent 产品？","description":"","frontmatter":{"editLink":"https://github.com/SyncLionPaw/bagent/edit/main/lessons/38-agent-product/doc.md"},"headers":[],"relativePath":"chapters/38-agent-product.md","filePath":"chapters/38-agent-product.md"}'),r={name:"chapters/38-agent-product.md"};function o(d,t,h,l,p,c){return a(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="第-38-课-·-还要什么-才算-code-agent-产品" tabindex="-1">第 38 课 · 还要什么，才算 Code Agent 产品？ <a class="header-anchor" href="#第-38-课-·-还要什么-才算-code-agent-产品" aria-label="Permalink to &quot;第 38 课 · 还要什么，才算 Code Agent 产品？&quot;">​</a></h1><p><strong>约 30 分钟</strong> · 纯阅读 · <a href="/bagent/chapters/37-two-loops.html">第 37 课</a> 之后 · <strong>第三阶段收官</strong></p><p><a href="/bagent/chapters/34-agent-thinking.html">第 34–36 课</a> 把 <strong>Agent 内核</strong> 补到能讲清原理：Thinking、审批、钩子。<br><a href="/bagent/chapters/37-two-loops.html">第 37 课</a> 说明：好用的交互必须 <strong>输入区 / 输出区分开</strong>——CLI 用 TUI，IDE 用 Webview，网页用 div + 输入框。</p><p>本课回答：<strong>内核跑通之后，完整产品通常长什么样？</strong> 你会看到三种常见形态，以及它们如何共用同一套 <code>loop</code> 和 <code>AgentEvent</code>。</p><hr><h2 id="_1-三种形态-一个内核" tabindex="-1">1. 三种形态，一个内核 <a class="header-anchor" href="#_1-三种形态-一个内核" aria-label="Permalink to &quot;1. 三种形态，一个内核&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                         ┌─────────────────────┐</span></span>
<span class="line"><span>                         │  Agent 内核（共享）   │</span></span>
<span class="line"><span>                         │  loop · events      │</span></span>
<span class="line"><span>                         │  hooks · tools      │</span></span>
<span class="line"><span>                         │  stream · approve   │</span></span>
<span class="line"><span>                         └──────────┬──────────┘</span></span>
<span class="line"><span>                                    │</span></span>
<span class="line"><span>         ┌──────────────────────────┼──────────────────────────┐</span></span>
<span class="line"><span>         ▼                          ▼                          ▼</span></span>
<span class="line"><span>┌─────────────────┐      ┌─────────────────┐      ┌─────────────────┐</span></span>
<span class="line"><span>│ ① CLI           │      │ ② IDE 插件       │      │ ③ 自有 UI        │</span></span>
<span class="line"><span>│ 终端 TUI 分屏    │      │ Webview 分屏     │      │ 你设计的前端      │</span></span>
<span class="line"><span>│                 │      │                 │      │ React / 网页…    │</span></span>
<span class="line"><span>└─────────────────┘      └─────────────────┘      └─────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th></th><th><strong>① CLI</strong></th><th><strong>② IDE 插件</strong></th><th><strong>③ 自有 UI</strong></th></tr></thead><tbody><tr><td><strong>谁用</strong></td><td>习惯终端的开发者</td><td>日常在 VS Code 等 IDE 里的人</td><td>要自定义界面、内网控制台、品牌站的人</td></tr><tr><td><strong>壳是什么</strong></td><td>Ink / blessed 等 TUI</td><td><a href="/bagent/chapters/31-vscode-spawn.html">第 31–32 课</a> 的 Webview</td><td>任意前端（<a href="/bagent/chapters/28-agent-network.html">第 28 课</a> SSE、<a href="/bagent/chapters/20-web-stream-server.html">第 20 课</a> 网关）</td></tr><tr><td><strong>怎么连内核</strong></td><td>进程内 <code>for await (turn)</code></td><td>stdio 一行一条 JSON（worker）</td><td>HTTP/SSE；审批用带 <code>id</code> 的回包</td></tr><tr><td><strong>谁画 UI</strong></td><td>CLI 程序里的 TUI 组件</td><td>插件里的 Webview</td><td><strong>你的</strong> HTML / React</td></tr><tr><td><strong>内核从哪来</strong></td><td>与 ch36 同构的 <code>loop</code></td><td>迁入 worker 的同一份代码</td><td>同一 <code>server</code> 或同包 <code>import</code></td></tr></tbody></table><p>要点：<strong>不是抄三份 Loop</strong>——而是 <strong><code>AgentEvent</code> 稳定</strong>，三种壳各自负责 <strong>渲染 + 传输</strong>。</p><p><a href="/bagent/chapters/29-agent-split.html">第 29 课</a> 说过：内核只产出事件，终端 / 网页 / IDE <strong>各自订阅</strong>。③ 是这一条在产品里的正式位置。</p><p><a href="/bagent/chapters/36-tool-hooks.html">第 36 课</a> 的 <code>npm run ch36</code> 是 <strong>内核实验台</strong>（readline 单屏，故意简陋，只教原理）。</p><hr><h2 id="_2-本教程里的-agent-边界" tabindex="-1">2. 本教程里的 Agent 边界 <a class="header-anchor" href="#_2-本教程里的-agent-边界" aria-label="Permalink to &quot;2. 本教程里的 Agent 边界&quot;">​</a></h2><p>学完第三阶段，你应该能说出「一个本机 Code Agent」通常包含什么、刻意不碰什么：</p><table tabindex="0"><thead><tr><th>要素</th><th>本教程范围</th></tr></thead><tbody><tr><td><strong>模型</strong></td><td>云端 API（DeepSeek 等），Key 放在 <code>~/.bagent/</code> 或 server 进程</td></tr><tr><td><strong>工具</strong></td><td><code>pwd</code> / <code>ls</code> / <code>read_file</code>（绝对路径）</td></tr><tr><td><strong>安全</strong></td><td>读项目须 <strong>审批</strong>；工具输出 <strong>截断</strong></td></tr><tr><td><strong>思考</strong></td><td>Thinking 与正文 <strong>分事件</strong>（<a href="/bagent/chapters/34-agent-thinking.html">第 34 课</a>）</td></tr><tr><td><strong>三种用法</strong></td><td>终端 TUI · IDE 插件 · 网页订阅 server</td></tr><tr><td><strong>刻意不做（现阶段）</strong></td><td>不写盘工具、不对标 Cursor 全功能、不先上 RAG / MCP 全家桶；写盘与 diff 预览见规划中的 <a href="/bagent/chapters/120-edit-diff.html">第 120 课</a></td></tr></tbody></table><hr><h2 id="_3-形态-1-终端-cli" tabindex="-1">3. 形态 ①：终端 CLI <a class="header-anchor" href="#_3-形态-1-终端-cli" aria-label="Permalink to &quot;3. 形态 ①：终端 CLI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ch36（你现在跑的）</th><th>像样的 CLI 产品</th></tr></thead><tbody><tr><td>readline，输出和输入抢一行</td><td><strong>TUI</strong>：上消息、下输入</td></tr><tr><td><code>npm run ch36</code></td><td>全局命令（如 <code>bagent</code>）</td></tr></tbody></table><p>要做成产品，壳侧至少要会：</p><table tabindex="0"><thead><tr><th>能力</th><th>为什么</th></tr></thead><tbody><tr><td>只根据 <code>AgentEvent</code> 渲染</td><td>和 <a href="/bagent/chapters/37-two-loops.html">第 37 课</a> 的分屏一致</td></tr><tr><td>内核抽成可 <code>import</code> 的包</td><td>CLI、worker、server <strong>共用</strong>，不复制粘贴</td></tr><tr><td><code>bin</code> 发布</td><td>别人一条命令能装</td></tr></tbody></table><hr><h2 id="_4-形态-2-ide-插件" tabindex="-1">4. 形态 ②：IDE 插件 <a class="header-anchor" href="#_4-形态-2-ide-插件" aria-label="Permalink to &quot;4. 形态 ②：IDE 插件&quot;">​</a></h2><p><a href="/bagent/chapters/31-vscode-spawn.html">第 31–32 课</a> 你已经见过雏形：插件 <code>spawn</code> worker，stdio 传 <code>AgentEvent</code>。</p><table tabindex="0"><thead><tr><th>31–32 课（现状）</th><th>对齐 ch36 之后</th></tr></thead><tbody><tr><td>较早的 6 种事件</td><td>Thinking、Pending、截断等 <strong>与 ch36 一致</strong></td></tr><tr><td>工具可能直接执行</td><td>Webview <strong>允许 / 拒绝</strong>（<a href="/bagent/chapters/35-tool-approval.html">第 35 课</a> 语义）</td></tr></tbody></table><p>插件作者大部分时间写的是 <strong>Webview + 编辑器 API</strong>，不是重写 Loop——这和 <a href="/bagent/chapters/29-agent-split.html">第 29 课</a> §3 一致。</p><hr><h2 id="_5-形态-3-自有-ui-开放订阅" tabindex="-1">5. 形态 ③：自有 UI（开放订阅） <a class="header-anchor" href="#_5-形态-3-自有-ui-开放订阅" aria-label="Permalink to &quot;5. 形态 ③：自有 UI（开放订阅）&quot;">​</a></h2><p><strong>不是第四种内核</strong>——是 <strong>不绑某一种官方壳</strong>，用你自己的页面连同一套 Agent。</p><h3 id="_5-1-为什么需要这一档" tabindex="-1">5.1 为什么需要这一档 <a class="header-anchor" href="#_5-1-为什么需要这一档" aria-label="Permalink to &quot;5.1 为什么需要这一档&quot;">​</a></h3><ul><li>有人要 <strong>品牌控制台、Electron 桌面、内网工作台</strong>——不一定用终端或 VS Code</li><li><a href="/bagent/chapters/28-agent-network.html">第 28 课</a> 已演示：<code>server</code> 产事件，<code>client</code> 只 <code>fetch</code> SSE</li><li><a href="/bagent/chapters/17-sse-landscape.html">第 17 课</a>：审批可走 <strong>JSON-RPC <code>request</code> + <code>id</code></strong>，前端回 <code>result</code> 即可</li></ul><p>你只写 <strong>订阅端 + 交互</strong>，不必重写 Loop。</p><h3 id="_5-2-典型接法" tabindex="-1">5.2 典型接法 <a class="header-anchor" href="#_5-2-典型接法" aria-label="Permalink to &quot;5.2 典型接法&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────┐     SSE / WebSocket      ┌──────────────────┐</span></span>
<span class="line"><span>│  你的 UI          │ ◄────────────────────── │  Agent server    │</span></span>
<span class="line"><span>│  React / Vue …    │ ── POST /chat ────────► │  loop + hooks     │</span></span>
<span class="line"><span>│  消息区 + 输入框   │ ◄── ApprovalRequest ── │  Key · tools      │</span></span>
<span class="line"><span>└──────────────────┘     POST /approve      └──────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>方向</th><th>传什么</th></tr></thead><tbody><tr><td><strong>server → UI</strong></td><td>一行一条 <code>AgentEvent</code> JSON（与 26、28、31 同构）</td></tr><tr><td><strong>UI → server</strong></td><td>用户消息、<code>approve</code> / <code>deny</code></td></tr><tr><td><strong>UI 不负责</strong></td><td><code>fetch</code> DeepSeek、跑 <code>read_file</code>、拼 <code>messages</code></td></tr></tbody></table><h3 id="_5-3-自己写网页-ui-时还要补什么" tabindex="-1">5.3 自己写网页 UI 时还要补什么 <a class="header-anchor" href="#_5-3-自己写网页-ui-时还要补什么" aria-label="Permalink to &quot;5.3 自己写网页 UI 时还要补什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td><strong>HTTP API</strong></td><td>POST 发话、SSE 收事件、POST 审批（在 ch28 server 上升格）</td></tr><tr><td><strong>类型或 Schema</strong></td><td><code>AgentEvent</code> 字段固定，前端不用猜</td></tr><tr><td><strong>事件表</strong></td><td>Thinking / Pending / <code>truncated</code> 各怎么画</td></tr><tr><td><strong>CORS / localhost</strong></td><td>浏览器连本机端口（20、28 课已有先例）</td></tr></tbody></table><h3 id="_5-4-与-cli-插件的关系" tabindex="-1">5.4 与 CLI / 插件的关系 <a class="header-anchor" href="#_5-4-与-cli-插件的关系" aria-label="Permalink to &quot;5.4 与 CLI / 插件的关系&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>CLI / 插件</th><th>自有 UI</th></tr></thead><tbody><tr><td>界面谁写</td><td>教程示例里的 TUI / Webview</td><td><strong>你</strong></td></tr><tr><td>内核</td><td>同一份 <code>loop</code></td><td>连同一个 server 或同包 import</td></tr><tr><td>能力对齐</td><td>靠 <strong>同一套 <code>AgentEvent</code></strong></td><td>同上</td></tr></tbody></table><p>插件 worker = <strong>stdio 版 server</strong>；网页 = <strong>HTTP 版 server</strong>——内核一份，管道不同。</p><hr><h2 id="_6-共享内核-只写一次" tabindex="-1">6. 共享内核：只写一次 <a class="header-anchor" href="#_6-共享内核-只写一次" aria-label="Permalink to &quot;6. 共享内核：只写一次&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/agent（概念上由 ch36 升格）</span></span>
<span class="line"><span>  events · loop · hooks · tools · stream</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├──► cli/tui           → ①</span></span>
<span class="line"><span>        ├──► agent/worker.ts   → ②</span></span>
<span class="line"><span>        └──► server.ts         → ③</span></span></code></pre></div><table tabindex="0"><thead><tr><th>内核做一次</th><th>各壳只做</th></tr></thead><tbody><tr><td>协议、钩子、工具</td><td><strong>渲染</strong> + <strong>传输</strong></td></tr><tr><td><code>approve</code> 语义</td><td>终端 <code>y/N</code> / 按钮 / HTTP 回包</td></tr></tbody></table><hr><h2 id="_7-三种形态对照" tabindex="-1">7. 三种形态对照 <a class="header-anchor" href="#_7-三种形态对照" aria-label="Permalink to &quot;7. 三种形态对照&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① CLI          进程内 turn + TUI 渲染</span></span>
<span class="line"><span>② 插件         worker stdio + Webview</span></span>
<span class="line"><span>③ 自有 UI      server SSE + 任意前端（输入输出天然分屏）</span></span></code></pre></div><p>③ 往往 <strong>最容易做好分屏</strong>——浏览器的 div + textarea 本来就在 <a href="/bagent/chapters/37-two-loops.html">第 37 课</a> 说的「正确分区」里。</p><hr><h2 id="_8-第四部分预告" tabindex="-1">8. 第四部分预告 <a class="header-anchor" href="#_8-第四部分预告" aria-label="Permalink to &quot;8. 第四部分预告&quot;">​</a></h2><p>第三阶段（22–38）把 <strong>内核原理 + 产品全景</strong> 讲完。第四部分（39 课起）会 <strong>动手</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>39   ACP：IDE 怎么连 Agent（纯阅读）</span></span>
<span class="line"><span>40+  内核抽包 → CLI TUI / 插件对齐 ch36 / server + 示例 UI</span></span></code></pre></div><p><a href="/bagent/chapters/39-agent-client-protocol.html">第 39 课</a> 先讲 <strong>ACP</strong>——行业里 IDE 接 Agent 的开放协议，再写代码。</p><p>动手前，先分清你要改的是 <strong>内核</strong> 还是某一个 <strong>壳</strong>；三种形态应共用同一套事件，不要复制三份 <code>loop.ts</code>。</p><hr><h2 id="_9-教程课-vs-产品壳" tabindex="-1">9. 教程课 vs 产品壳 <a class="header-anchor" href="#_9-教程课-vs-产品壳" aria-label="Permalink to &quot;9. 教程课 vs 产品壳&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>教程（如 ch36）</th><th>① CLI</th><th>② 插件</th><th>③ 自有 UI</th></tr></thead><tbody><tr><td>目的</td><td>学内核</td><td>终端里用</td><td>IDE 里用</td><td>自己的界面</td></tr><tr><td>ch36</td><td>直接跑</td><td>将来 TUI 包一层</td><td>worker 复用代码</td><td>server 复用代码</td></tr><tr><td>ch28</td><td>双进程入门</td><td>—</td><td>—</td><td><strong>订阅范式</strong></td></tr></tbody></table><hr><h2 id="_10-本教程刻意不碰的-先建立预期" tabindex="-1">10. 本教程刻意不碰的（先建立预期） <a class="header-anchor" href="#_10-本教程刻意不碰的-先建立预期" aria-label="Permalink to &quot;10. 本教程刻意不碰的（先建立预期）&quot;">​</a></h2><ul><li>不做 Cursor 全量替代</li><li>不做云端多租户沙箱（网页 UI 仍连 <strong>本机 server</strong>）</li><li>不在 readline 单屏上冒充「正式 CLI」</li><li>不维护多套 <code>loop</code> / 多套事件名</li><li>不先 RAG / MCP 全家桶（第四部分以后按需加）</li></ul><hr><h2 id="检查点" tabindex="-1">检查点 <a class="header-anchor" href="#检查点" aria-label="Permalink to &quot;检查点&quot;">​</a></h2><ul><li>[ ] 三种形态分别是什么？共用什么是？</li><li>[ ] 自有 UI 和 <a href="/bagent/chapters/28-agent-network.html">第 28 课</a> client 有什么关系？</li><li>[ ] 审批在三种形态里各怎么回传？</li><li>[ ] 为什么自有 UI 往往最容易做「上下分屏」？</li><li>[ ] ch36 的 readline 和正式 CLI 产品差在哪？</li></ul><hr><p><a href="/bagent/chapters/37-two-loops.html">← 第 37 课</a> · <a href="/bagent/chapters/39-agent-client-protocol.html">第 39 课 · ACP</a> · <a href="/bagent/chapters/28-agent-network.html">第 28 课</a> · <a href="/bagent/chapters/36-tool-hooks.html">第 36 课</a></p>`,64)])])}const b=e(r,[["render",o]]);export{g as __pageData,b as default};
